def left_half_pyramid(n):
    for i in range(1, n + 1):                  # row i needs n - i spaces then i stars
        for j in range(n):                      # check every one of the n column positions
            if j < n - i:
                print(" ", end="")                 # still inside the leading gap
            else:
                print("*", end="")                 # inside the star region
        print()                                 # move to the next line after the row


if __name__ == "__main__":
    left_half_pyramid(4)

