import java.util.*;

public class Main {
    void leftHalfPyramid(int n) {
        for (int i = 1; i <= n; i++) {                // row i needs n - i spaces then i stars
            for (int j = 0; j < n; j++) {              // check every one of the n column positions
                if (j < n - i) {
                    System.out.print(" ");                // still inside the leading gap
                } else {
                    System.out.print("*");                // inside the star region
                }
            }
            System.out.println();                     // move to the next line after the row
        }
    }

    public static void main(String[] args) {
        Main solution = new Main();
        solution.leftHalfPyramid(4);
    }
}

