import java.util.*;

public class Main {
    void leftHalfPyramid(int n) {
        StringBuilder sb = new StringBuilder();
        for (int i = 1; i <= n; i++) {
            sb.append(" ".repeat(n - i)).append("*".repeat(i));  // build every row directly, one operation each
            if (i < n) {
                sb.append('\n');
            }
        }
        System.out.println(sb);                      // output the whole pattern with a single call
    }

    public static void main(String[] args) {
        Main solution = new Main();
        solution.leftHalfPyramid(4);
    }
}

